package paxoslocker.grader;
import paxoslocker.testkit.*; import org.junit.jupiter.api.*; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*;
@Tag("framework") class FrameworkContractTest { @Test void seedIsAlwaysExposed(){assertNotNull(System.getProperty("paxos.seed"));} @Test void tempDirectoryIsIsolated() throws Exception {Path p=Files.createTempDirectory("grader-cold-start-");try{assertEquals(0,Files.list(p).count());}finally{Files.deleteIfExists(p);}} @Test void chosenConflictUsesStructuredCapMarker(){var failure=new SafetyViolationException(SafetyViolationKind.CHOSEN_CONFLICT,"slot 1");assertEquals(SafetyViolationKind.CHOSEN_CONFLICT,failure.kind());assertTrue(failure.getMessage().startsWith("SAFETY_CHOSEN_CONFLICT:"));} }
